TLM.f("Tempora/Quad5-5",{"officium":"Septem Dolorum Beatæ Mariæ Virgine","rule":["no Gloria","Credo","Prefatio=Quad5"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"fallback":"Tempora/Quad5-0","sections":{"Introitus":[{"k":"ref","la":"Joann 19:25"},{"k":"text","la":"Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et Salóme et María Magdaléne."},{"k":"ref","la":"Joann 19:26-27"},{"k":"text","la":"Múlier, ecce fílius tuus: dixit Jesus; ad discípulum autem: Ecce Mater tua."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et Salóme et María Magdaléne."}],"Oratio":[{"k":"text","la":"Deus, in cuius passióne, secúndum Simeónis prophetíam, dulcíssimam ánimam gloriósae Vírginis et Matris Maríae dolóris gládius pertransívit: concéde propítius; ut, qui dolóres eius venerándo recólimus, passiónis tuae efféctum felícem consequámur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Judith."},{"k":"ref","la":"Judith 13:22, 23-25"},{"k":"text","la":"Benedíxit te Dóminus in virtúte sua, quia per te ad níhilum redégit inimícos nostros. Benedícta es tu, fília, a Dómino, Deo excélso, præ ómnibus muliéribus super terram. Benedíctus Dóminus, qui creávit cœlum et terram: quia hódie nomen tuum ita magnificávit, ut non recédat laus tua de ore hóminum, qui mémores fúerint virtútis Dómini in ætérnum, pro quibus non pepercísti ánimæ tuæ propter angústias et tribulatiónem géneris tui, sed subvenísti ruínæ ante conspéctum Dei nostri."}],"Graduale":[{"k":"text","la":"Dolorósa et lacrimábilis es, Virgo María, stans juxta Crucem Dómini Jesu, Fílii tui, Redemptóris."},{"k":"text","la":"Virgo Dei Génetrix, quem totus non capit orbis, hoc crucis fert supplícium, auctor vitæ factus homo.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"text","la":"Stabat sancta María, cœli Regína et mundi Dómina, juxta Crucem Dómini nostri Jesu Christi dolorósa."},{"k":"ref","la":"Thren 1:12"},{"k":"text","la":"O vos omnes, qui tránsitis per viam, atténdite et vidéte, si est dolor sicut dolor meus."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Stabat sancta María, cœli Regína et mundi Dómina, juxta Crucem Dómini nostri Jesu Christi dolorósa. Allelúja","mark":"V"},{"k":"ref","la":"Thren 1:12"},{"k":"text","la":"O vos omnes, qui tránsitis per viam, atténdite et vidéte, si est dolor sicut dolor meus. Allelúja."}],"Sequentia":[{"k":"text","la":"Stabat Mater dolorósa"},{"k":"text","la":"Juxta Crucem lacrimósa,"},{"k":"text","la":"Dum pendébat Fílius."},{"k":"sep"},{"k":"text","la":"Cujus ánimam geméntem,"},{"k":"text","la":"Contristátam et doléntem"},{"k":"text","la":"Pertransívit gládius."},{"k":"sep"},{"k":"text","la":"O quam tristis et afflícta"},{"k":"text","la":"Fuit illa benedícta"},{"k":"text","la":"Mater Unigéniti!"},{"k":"sep"},{"k":"text","la":"Quæ mærébat et dolébat,"},{"k":"text","la":"Pia Mater, dum vidébat"},{"k":"text","la":"Nati pœnas íncliti."},{"k":"sep"},{"k":"text","la":"Quis est homo, qui non fleret,"},{"k":"text","la":"Matrem Christi si vidéret"},{"k":"text","la":"In tanto supplício?"},{"k":"sep"},{"k":"text","la":"Quis non posset contristári,"},{"k":"text","la":"Christi Matrem contemplári"},{"k":"text","la":"Doléntem cum Fílio?"},{"k":"sep"},{"k":"text","la":"Pro peccátis suæ gentis"},{"k":"text","la":"Vidit Jesum in torméntis"},{"k":"text","la":"Et flagéllis súbditum."},{"k":"sep"},{"k":"text","la":"Vidit suum dulcem"},{"k":"text","la":"Natum Moriéndo desolátum,"},{"k":"text","la":"Dum emísit spíritum."},{"k":"sep"},{"k":"text","la":"Eja, Mater, fons amóris,"},{"k":"text","la":"Me sentíre vim dolóris"},{"k":"text","la":"Fac, ut tecum lúgeam."},{"k":"sep"},{"k":"text","la":"Fac, ut árdeat cor meum"},{"k":"text","la":"In amándo Christum Deum,"},{"k":"text","la":"Ut sibi compláceam."},{"k":"sep"},{"k":"text","la":"Sancta Mater, istud agas,"},{"k":"text","la":"Crucifixi fige plagas"},{"k":"text","la":"Cordi meo válida."},{"k":"sep"},{"k":"text","la":"Tui Nati vulneráti,"},{"k":"text","la":"Tam dignáti pro me pati,"},{"k":"text","la":"Pœnas mecum dívide."},{"k":"sep"},{"k":"text","la":"Fac me tecum pie flere,"},{"k":"text","la":"Crucifíxo condolére,"},{"k":"text","la":"Donec ego víxero."},{"k":"sep"},{"k":"text","la":"Juxta Crucem tecum stare"},{"k":"text","la":"Et me tibi sociáre"},{"k":"text","la":"In planctu desídero."},{"k":"sep"},{"k":"text","la":"Virgo vírginum præclára."},{"k":"text","la":"Mihi jam non sis amára:"},{"k":"text","la":"Fac me tecum plángere."},{"k":"sep"},{"k":"text","la":"Fac, ut portem Christi mortem,"},{"k":"text","la":"Passiónis fac consórtem"},{"k":"text","la":"Et plagas recólere."},{"k":"sep"},{"k":"text","la":"Fac me plagis vulnerári,"},{"k":"text","la":"Fac me Cruce inebriári"},{"k":"text","la":"Et cruóre Fílii."},{"k":"sep"},{"k":"text","la":"Flammis ne urar succénsus,"},{"k":"text","la":"Per te, Virgo, sim defénsus"},{"k":"text","la":"In die judícii."},{"k":"sep"},{"k":"text","la":"Christe, cum sit hinc exíre."},{"k":"text","la":"Da per Matrem me veníre"},{"k":"text","la":"Ad palmam victóriæ."},{"k":"sep"},{"k":"text","la":"Quando corpus moriétur,"},{"k":"text","la":"Fac, ut ánimæ donétur"},{"k":"text","la":"Paradísi glória."},{"k":"text","la":"Amen."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem. P"},{"k":"ref","la":"Joann 19:25-27"},{"k":"text","la":"In illo témpore: Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et María Magdaléne. Cum vidísset ergo Jesus Matrem, et discípulum stantem, quem diligébat, dicit Matri suæ: Múlier, ecce fílius tuus. Deinde dicit discípulo: Ecce Mater tua. Et ex illa hora accépit eam discípulus in sua."}],"Offertorium":[{"k":"ref","la":"Jer 18:20"},{"k":"text","la":"Recordáre, Virgo Mater, in conspéctu Dei, ut loquáris pro nobis bona, et ut avértat indignatiónem suam a nobis."}],"Secreta":[{"k":"text","la":"Offérimus tibi preces et hóstias, Dómine Jesu Christe, humíliter supplicántes: ut, qui Transfixiónem dulcíssimi spíritus beátæ Maríæ, Matris tuæ, précibus recensémus; suo suorúmque sub Cruce Sanctórum consórtium multiplicáto piíssimo intervéntu, méritis mortis tuæ, méritum cum beátis habeámus:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"text","la":"Felices sensus beátæ Maríæ Vírginis, qui sine morte meruérunt martýrii palmam sub Cruce Dómini."}],"Postcommunio":[{"k":"text","la":"Sacrifícia, quæ súmpsimus, Dómine Jesu Christe, Transfixiónem Matris tuæ et Vírginis devóte celebrántes: nobis ímpetrent apud cleméntiam tuam omnis boni salutáris efféctum:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Feria"},{"k":"text","la":"Córdibus nostris, quǽsumus, Dómine, grátiam tuam benígnus infúnde: ut peccáta nostra castigatióne voluntária cohibéntes, temporáliter pótius macerémur, quam súppliciis deputémur ætérnis."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Feria"},{"k":"text","la":"Præsta nobis, miséricors Deus: ut digne tuis servíre semper altáribus mereámur; et eórum perpétua participatióne salvári."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Feria"},{"k":"text","la":"Sumpti sacrifícii, Dómine, perpetua nos tuítio non derelínquat: et nóxia semper a nobis cuncta depéllat."},{"k":"macro","name":"Per Dominum"}],"GradualeA":[{"k":"text","la":"Dolorósa et lacrimábilis es, Virgo María, stans juxta Crucem Dómini Jesu, Fílii tui, Redemptóris."},{"k":"text","la":"Virgo Dei Génetrix, quem totus non capit orbis, hoc crucis fert supplícium, auctor vitæ factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Stabat sancta María, cœli Regína et mundi Dómina, juxta Crucem Dómini nostri Jesu Christi dolorósa. Allelúja.","mark":"V"}]},"hr":{"8da64354b6faaca3":{"t":"<i>Pomolimo se</i>.\nBože, za vrijeme tvoje muke mač je boli prostrijelio po Šimunovu proročanstvu presvetu dušu slavne Djevice i majke Marije: daj milostivo, da mi koji s poštovanjem slavimo njezine žalosti postignemo sretni učinak tvoje muke:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"15d27ce9c9f0fb0d":{"t":"Prinosimo ti molitve i darove, Gospodine Isuse Kriste, ponizno moleći, da mi koji u molitvama razmišljamo o žalostima presvete duše blažene Marije Majke tvoje po milom zagovoru njezinu i njezinih svetih pratilaca pod križem zavrijedimo sudjelovati u nagradi svetih po zaslugama tvoje smrti:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f24543bf9f3bd47e":{"t":"<i>Pomolimo se</i>.\nŽrtve koje smo primili, Gospodine Isuse Kriste, slaveći pobožno žalosti tvoje Majke i Djevice, neka nam izmole kod tvoje dobrote svako spasonosno dobro:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
